import * as monaco from "monaco-editor";
import { loader } from "@monaco-editor/react";
import EditorWorker from "../../../node_modules/monaco-editor/esm/vs/editor/editor.worker.js?worker";

// @monaco-editor/react falls back to a CDN-style dynamic import when no worker
// factory is registered. That path is not served by Vite previews, so provide
// the worker bundle generated by Vite instead.
if (typeof self !== "undefined") {
  self.MonacoEnvironment = {
    getWorker() {
      return new EditorWorker();
    }
  };
}

loader.config({ monaco });

const LANGUAGE_ID = "compiscript";
let registered = false;

/** Registers the Compiscript Monarch grammar and the two IDE themes once. */
export function ensureCompiscriptLanguage(): void {
  if (registered) return;
  registered = true;

  monaco.languages.register({ id: LANGUAGE_ID });

  monaco.languages.setLanguageConfiguration(LANGUAGE_ID, {
    comments: { lineComment: "//" },
    brackets: [
      ["{", "}"],
      ["[", "]"],
      ["(", ")"]
    ],
    autoClosingPairs: [
      { open: "{", close: "}" },
      { open: "[", close: "]" },
      { open: "(", close: ")" },
      { open: '"', close: '"' }
    ]
  });

  monaco.languages.setMonarchTokensProvider(LANGUAGE_ID, {
    keywords: [
      "let", "var", "const", "function", "class", "print", "if", "else", "while", "do",
      "for", "foreach", "in", "break", "continue", "return", "try", "catch", "switch",
      "case", "default", "new", "this"
    ],
    typeKeywords: ["boolean", "integer", "float", "string"],
    constants: ["true", "false", "null"],
    operators: ["=", "==", "!=", "<=", ">=", "<", ">", "!", "&&", "||", "+", "-", "*", "/", "%"],
    symbols: /[=><!~?:&|+\-*/^%]+/,
    tokenizer: {
      root: [
        [
          /[a-zA-Z_]\w*/,
          {
            cases: {
              "@keywords": "keyword",
              "@typeKeywords": "type",
              "@constants": "constant",
              "@default": "identifier"
            }
          }
        ],
        [/\d+\.\d+/, "number.float"],
        [/\d+/, "number"],
        [/"([^"\\]|\\.)*"/, "string"],
        [/\/\/.*$/, "comment"],
        [
          /@symbols/,
          {
            cases: {
              "@operators": "operator",
              "@default": ""
            }
          }
        ]
      ]
    }
  });

  monaco.editor.defineTheme("compiscript-light", {
    base: "vs",
    inherit: true,
    rules: [
      { token: "keyword", foreground: "5b4bea", fontStyle: "bold" },
      { token: "type", foreground: "087f8c" },
      { token: "constant", foreground: "7c3aed" },
      { token: "string", foreground: "087f5b" },
      { token: "number", foreground: "b45309" },
      { token: "comment", foreground: "76809b", fontStyle: "italic" }
    ],
    colors: {
      "editor.background": "#f7f9ff",
      "editor.foreground": "#11172a",
      "editorLineNumber.foreground": "#8a94ae",
      "editor.lineHighlightBackground": "#e9edfb",
      "editorCursor.foreground": "#6d5dfc",
      "editor.selectionBackground": "#6d5dfc33",
      "editorIndentGuide.background1": "#dce2f2"
    }
  });

  monaco.editor.defineTheme("compiscript-dark", {
    base: "vs-dark",
    inherit: true,
    rules: [
      { token: "keyword", foreground: "A89BFF", fontStyle: "bold" },
      { token: "type", foreground: "67E8F9" },
      { token: "constant", foreground: "D8B4FE" },
      { token: "string", foreground: "6EE7B7" },
      { token: "number", foreground: "FDBA74" },
      { token: "comment", foreground: "68718E", fontStyle: "italic" }
    ],
    colors: {
      "editor.background": "#080B14",
      "editor.foreground": "#DDE3F8",
      "editorLineNumber.foreground": "#4F5874",
      "editor.lineHighlightBackground": "#11172A",
      "editorCursor.foreground": "#9A8CFF",
      "editor.selectionBackground": "#6D5DFC45",
      "editorIndentGuide.background1": "#1A2137",
      "editorWhitespace.foreground": "#27304A"
    }
  });
}

export { monaco, LANGUAGE_ID };
